"""Explicit census of tests made OBSOLETE by Hlith Review (product.REVIEW_ONLY, P2.6). Each is skipped by tests/conftest.py with
its reason; nothing else is skipped by this mechanism. review test posture, 2026-11-27, base a6cbbe8a.

Admission rule: the test exercises ONLY a route Review does not offer (run/resume/legacy engine/worker command/--events-out/
screen-started check/Running screen/screen Apply) AND every behaviour it checks that Review still offers was retargeted to
`hlith check` or to the review-only contract in a named test. Each entry was observed failing on the supported host at a6cbbe8a
and its body was inspected for the removed route, except `apply-static` entries (static inspection only, said in their reason). tests/test_obsolete_census.py keeps every entry pointing at a real test."""

REASONS: dict[str, str] = {
    'run': 'drives `hlith run` (engine_cli), not offered in Hlith Review (P2.6, product.REVIEW_ONLY): the public CLI has no `run` and the engine dispatcher refuses it with boundary exit 4 before any work (tests/test_review_product.py::test_cli_run_and_resume_are_disabled)',
    'resume': 'drives `hlith resume` of a parked/interrupted thread, not offered in Hlith Review (P2.6): refused with boundary exit 4 before any work (tests/test_review_product.py::test_cli_run_and_resume_are_disabled)',
    'legacy': 'drives the legacy LangGraph/Layer-1 engine (`hlith run --engine legacy --layer1 langgraph`), not offered in Hlith Review (P2.6)',
    'events': "drives `hlith run --events-out` (the flag exists only on `run`), not offered in Hlith Review (P2.6); `hlith check` records the run's events in its own run folder (tests/operator/tui/test_walk_final.py)",
    'worker': 'drives `hlith run --worker-cmd` (a confined worker writes the change), not offered in Hlith Review (P2.6); a supplied change is reviewed with `hlith check --patch` (tests/test_obligation_scope_guard_case4.py)',
    'tui-start': "drives the engine as started by the terminal screen (`run --surface-mode standalone`); Hlith Review's screen starts no check (tests/test_tui_launch.py review-only start tests)",
    'running': "needs the Running screen, reached only by a check the terminal screen started; Hlith Review's screen starts no check, so the screen is unreachable (tests/operator/tui/test_journey_sizes.py::_to_running fails plainly if run)",
    'apply': "drives the terminal screen's Apply to the original repository, not offered in Hlith Review (frame._apply_candidate is False: tests/test_review_product.py::test_tui_apply_candidate_is_never_offered_even_for_landed_rehearsal)",
    'apply-static': "drives the terminal screen's Apply to the original repository (opens the Apply Claim with `l` after a rehearsal the screen started), not offered in Hlith Review (frame._apply_candidate is False); admitted by static inspection, not observed failing: the bounded TUI group ended before reaching it",
}

